function sv3_questions_db(int$vid):array{$qs=db_rows("SELECT id,QuestionCode questionCode,QuestionType questionType,Title title,HelpText helpText,IsRequired isRequired,MinSelections minSelections,MaxSelections maxSelections,RandomizeOptions randomizeOptions,AllowComment allowComment,ValidationJson validationJson,DisplayConditionJson displayConditionJson,ResultVisibility resultVisibility,SortOrder sortOrder FROM SafetyVote_Questions WHERE CampaignVersionID=? AND Status='Active' ORDER BY SortOrder,id",[$vid]);foreach($qs as&$q){$q['isRequired']=(bool)$q['isRequired'];$q['randomizeOptions']=(bool)$q['randomizeOptions'];$q['allowComment']=(bool)$q['allowComment'];$q['minSelections']=(int)$q['minSelections'];$q['maxSelections']=(int)$q['maxSelections'];$q['validation']=json_decode((string)$q['validationJson'],true)?:[];$q['displayCondition']=$q['displayConditionJson']?json_decode((string)$q['displayConditionJson'],true):null;$q['options']=db_rows("SELECT id,QuestionID questionId,OptionCode optionCode,Label label,Description description,ScoreValue scoreValue,IsAbstain isAbstain,FileID fileId,SortOrder sortOrder FROM SafetyVote_Options WHERE QuestionID=? AND Status='Active' ORDER BY SortOrder,id",[$q['id']]);foreach($q['options']as&$o){$o['isAbstain']=(bool)$o['isAbstain'];$o['scoreValue']=$o['scoreValue']===null?null:(float)$o['scoreValue'];}unset($o);}unset($q);return$qs;}
function sv3_eligible(array$c,string$employee):?array{return db_row("SELECT e.SnapshotID FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id WHERE s.CampaignVersionID=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1",[$c['CurrentVersionID'],$employee]);}
function sv3_answer_files_valid(array$answers,array$c,string$employee):bool{$expected=[];foreach($answers as$a)foreach(($a['rows']??[])as$r)if(!empty($r['fileId']))$expected[(int)$r['fileId']]=(int)$a['questionId'];if(!$expected)return true;$marks=implode(',',array_fill(0,count($expected),'?'));$params=array_merge([(int)$c['id'],(int)$c['CurrentVersionID'],$employee],array_keys($expected));$rows=db_rows("SELECT id,QuestionID FROM SafetyVote_Files WHERE CampaignID=? AND CampaignVersionID=? AND UploadedBy=? AND Status='Active' AND id IN ($marks)",$params);if(count($rows)!==count($expected))return false;foreach($rows as$r)if(($expected[(int)$r['id']]??null)!==(int)$r['QuestionID'])return false;return true;}
function sv3_event(array$u,string$a,int$cid,string$type,int$id,string$detail,array$meta=[]):void{sv_audit($u,$a,$type,(string)$id,$detail,$meta,$cid,null);}
function sv3_upload(array$u,array$c,?int$submissionId,?int$questionId,string$purpose):array{$f=$_FILES['file']??null;if(!$f||(int)$f['error']!==UPLOAD_ERR_OK||(int)$f['size']>10*1024*1024)json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED','message'=>'A file not exceeding 10 MB is required.'],400);$mime=sv_file_mime((string)$f['tmp_name']);if(!$mime||!in_array($mime,['image/jpeg','image/png','image/webp','application/pdf'],true))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED','message'=>'File signature is invalid.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp','application/pdf'=>'.pdf'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=sv_private_dir().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$f['tmp_name'],$target))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED','message'=>'Unable to store file.'],500);try{db_execute('INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,SubmissionID,QuestionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[(int)$c['id'],(int)$c['CurrentVersionID'],$submissionId,$questionId,$purpose,$stored,sv3_text($f['name']??'',255),$mime,(int)$f['size'],hash_file('sha256',$target),sv_actor($u)]);return['id'=>(int)db()->lastInsertId(),'stored'=>$stored,'mime'=>$mime,'size'=>(int)$f['size']];}catch(Throwable$e){@unlink($target);throw$e;}}
